// ============================================================
// ORCHESTRATOR WEB — Preparar Envio v1.0.0 (F6 Fase 1)
// Sobre canonico del agente -> respuesta JSON para el widget.
// Mantiene los MISMOS campos _underscore que '📤 Preparar Envio
// Telegram' para reutilizar la cola de sesion sin cambios
// ('📦 Payload — Update Session' / '📦 Payload — Guardar Mensaje
// Saliente' leen estos campos).
// ============================================================
const a = $json;

const rawSessionId  = a.sessionId;
const safeSessionId = (rawSessionId !== null && rawSessionId !== undefined &&
                       Number.isInteger(Number(rawSessionId)) &&
                       Number(rawSessionId) > 0)
  ? Number(rawSessionId)
  : null;
if (!safeSessionId) {
  console.error(`[PANGI-WEB] sessionId invalido del agente: "${rawSessionId}". Agent: ${a.newActiveAgent}`);
}

const text = a.responseText || 'Error interno. Por favor escribe de nuevo.';

// buttons: MISMO contrato que Telegram — [{text,data}] o filas [[...],[...]].
// Hoy NINGUN motor emite 'buttons' (UX-BTN parked) -> normalmente [].
// El widget ya sabe renderizarlos cuando lleguen; cero cambios aqui.
const _btns = Array.isArray(a.buttons) && a.buttons.length ? a.buttons : [];
const _rows = _btns.length ? (Array.isArray(_btns[0]) ? _btns : _btns.map(b => [b])) : [];
const buttons = _rows.map(r => r.map(b => ({
  text: String(b.text || '').slice(0, 64),
  data: String(b.data || b.text || '').slice(0, 64)
})));

const bodyOut = {
  conversationId: a.remoteJid || null,
  agent:          a.newActiveAgent || 'NOVA',
  text,
  buttons
};

return [{ json: {
  // cuerpo que el webhook responde al browser (via '📤 Respuesta al Widget')
  body: bodyOut,
  // passthrough para la cola de sesion (identico a la version Telegram)
  _responseText:      a.responseText || '',
  _remoteJid:         a.remoteJid || null,
  _instance:          a.instance || 'web',
  _userId:            a.userId,
  _sessionId:         safeSessionId,
  _newActiveAgent:    a.newActiveAgent  || 'NOVA',
  _newSessionState:   a.newSessionState || 'active',
  _newSessionContext: a.newSessionContext || {}
}}];
